let s,selection=[],camera={x:460,y:1000,z:1},vw=0,vh=0,dpr=1,started=false,paused=false,buildMode=null,orderMode=false,pointer=null,hover=null,keys={},last=0,acc=0,uiTick=0,saveTick=0,toastTimer;
const rnd=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),sideColor=t=>t===0?'#6ba9c0':'#c16e54';
function notice(text){if(/就绪|完成/.test(text))art?.sound('ready');$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3100)}
function entity(kind,team,x,y,extra={}){const d=defs[kind];return {id:s.id++,kind,team,x,y,hp:d.hp,maxhp:d.hp,complete:true,queue:[],cool:0,order:null,path:[],...extra}}
