function drawMini(){mc.drawImage(terrain,0,0,mini.width,mini.height);const sx=mini.width/W,sy=mini.height/H;for(const b of s.buildings){mc.fillStyle=sideColor(b.team);mc.fillRect(b.x*sx-3,b.y*sy-3,6,6)}for(const u of s.units){mc.fillStyle=u.team?'#ef9c7a':'#a9def1';mc.fillRect(u.x*sx-1,u.y*sy-1,2,2)}mc.strokeStyle='#fff3bd';mc.lineWidth=1;mc.strokeRect((camera.x-vw/2/camera.z)*sx,(camera.y-vh/2/camera.z)*sy,vw/camera.z*sx,vh/camera.z*sy)}
function select(ids){selection=ids;buildMode=null;orderMode=false;renderUI()}
function command(p,target){art?.sound('command');const units=selection.map(byId).filter(e=>e&&!isBuilding(e));if(!units.length)return;let count=0;for(let i=0;i<units.length;i++){const u=units[i];if(target?.team===1)order([u],{type:'attack',id:target.id});else if(target?.amount&&u.kind==='villager')order([u],{type:'gather',id:target.id,resource:target.kind});else if(target?.team===0&&!target.complete&&isBuilding(target)&&u.kind==='villager')order([u],{type:'build',id:target.id});else{const off=units.length>1?20:0;order([u],{type:'move',x:clamp(p.x+(i%5-2)*off,25,W-25),y:clamp(p.y+(Math.floor(i/5)-Math.floor(units.length/10))*off,25,H-25)})}count++}if(count)s.effects.push({type:'command',x:p.x,y:p.y,life:.6,max:.6});orderMode=false}
function objectAt(p){return nearest(p,s.units.filter(u=>dist(u,p)<22/camera.z+5))||nearest(p,s.buildings.filter(b=>dist(b,{x:p.x,y:p.y+35})<defs[b.kind].r+30))||nearest(p,s.nodes.filter(n=>dist(n,p)<30))}
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',e=>{if(!started||paused||s.ended||pointer)return;e.preventDefault();const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;pointer={id:e.pointerId,x,y,cx:x,cy:y,startX:camera.x,startY:camera.y,type:e.pointerType,button:e.button,drag:false};canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;hover={x,y};if(!pointer||pointer.id!==e.pointerId)return;pointer.cx=x;pointer.cy=y;if(Math.hypot(x-pointer.x,y-pointer.y)>7)pointer.drag=true;if(pointer.drag&&(pointer.type==='touch'||pointer.button===1)){camera.x=pointer.startX-(x-pointer.x)/camera.z;camera.y=pointer.startY-(y-pointer.y)/camera.z;clampCamera()}});
canvas.addEventListener('pointerup',e=>{if(!pointer||pointer.id!==e.pointerId)return;const a=pointer;pointer=null;if(paused||s.ended)return;const p=screenToWorld(a.cx,a.cy);if(a.drag){if(a.type!=='touch'&&a.button===0){const start=screenToWorld(a.x,a.y);select(s.units.filter(u=>u.team===0&&u.x>=Math.min(start.x,p.x)&&u.x<=Math.max(start.x,p.x)&&u.y>=Math.min(start.y,p.y)&&u.y<=Math.max(start.y,p.y)).map(u=>u.id))}return}if(buildMode){place(p.x,p.y);return}const target=objectAt(p);if(a.button===2||orderMode){command(p,target);return}if(target?.team===0){if(selection.map(byId).some(u=>u?.kind==='villager')&&isBuilding(target)&&!target.complete)command(p,target);else select(e.shiftKey?[...new Set([...selection,target.id])]:[target.id]);return}if(selection.some(id=>{const u=byId(id);return u&&!isBuilding(u)})){command(p,target)}else if(target?.team===1)notice('赤焰军 · '+defs[target.kind].name+' · '+Math.ceil(target.hp)+' 生命');else select([])});
canvas.addEventListener('pointercancel',()=>pointer=null);canvas.addEventListener('wheel',e=>{e.preventDefault();camera.z*=e.deltaY>0?.9:1.1;clampCamera()},{passive:false});
mini.addEventListener('pointerdown',e=>{if(!started)return;const r=mini.getBoundingClientRect();camera.x=(e.clientX-r.left)/r.width*W;camera.y=(e.clientY-r.top)/r.height*H;clampCamera()});
function selectArmy(){const army=s.units.filter(u=>u.team===0&&u.kind!=='villager');select(army.map(u=>u.id));notice(army.length?'已选择 '+army.length+' 名士兵，点击目标指挥':'还没有军队，点击兵营训练士兵')}
function selectWorkers(){const idle=s.units.filter(u=>u.team===0&&u.kind==='villager'&&!u.order);if(idle.length){select(idle.map(u=>u.id));camera.x=idle[0].x;camera.y=idle[0].y;clampCamera();notice('已选择 '+idle.length+' 名空闲村民')}else{const u=s.units.find(u=>u.team===0&&u.kind==='villager');if(u){select([u.id]);camera.x=u.x;camera.y=u.y;clampCamera();notice('村民都在忙，已选择一名村民')}else notice('没有村民，请选择城镇中心训练')}}
function pause(value){if(!started||s.ended)return;paused=value;$('pause-screen').hidden=!paused;$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'继续':'暂停');renderUI();if(paused)save()}
function reset(){ $('end-dialog').close();$('pause-screen').hidden=true;$('pause').textContent='Ⅱ';localStorage.removeItem(SAVE);seed();notice('欢迎来到绿河谷地。你的村民已经开始采集资源。')}
$('start').onclick=()=>{art?.audioStart();$('welcome').close();if(!started)seed();else pause(false);notice('采集资源，发展经济，然后集结军队跨过绿河。')};
$('pause').onclick=()=>pause(!paused);$('resume').onclick=()=>pause(false);$('new-game').onclick=reset;$('restart').onclick=reset;$('select-army').onclick=selectArmy;$('select-workers').onclick=selectWorkers;
let pausedBeforeHelp=false;$('help').onclick=()=>{pausedBeforeHelp=paused;pause(true);$('help-dialog').showModal()};$('close-help').onclick=()=>$('help-dialog').close();$('help-dialog').addEventListener('close',()=>{if(!pausedBeforeHelp)pause(false)});
$('home').onclick=()=>{const town=s.buildings.find(b=>b.team===0&&b.kind==='town');if(town){camera.x=town.x;camera.y=town.y;clampCamera();select([town.id])}};$('zoomin').onclick=()=>{camera.z*=1.15;clampCamera()};$('zoomout').onclick=()=>{camera.z/=1.15;clampCamera()};document.querySelector('.brand').onclick=e=>{e.preventDefault();$('home').click()};
window.addEventListener('keydown',e=>{if(e.target.matches('select,input')||document.querySelector('dialog[open]'))return;keys[e.key.toLowerCase()]=true;if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();if(e.repeat)return;if(e.key===' ')pause(!paused);if(e.key.toLowerCase()==='q')selectArmy();if(e.key.toLowerCase()==='e')selectWorkers();if(e.key==='Escape'){buildMode=null;orderMode=false;renderUI()}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{keys={};save()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&started)pause(true)});window.addEventListener('pagehide',save);window.addEventListener('resize',resize);
function frame(now){const dt=Math.min((now-last)/1000||0,.1);last=now;if(started&&!paused&&!s.ended){const speed=360/camera.z*dt;camera.x+=((keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0))*speed;camera.y+=((keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0))*speed;clampCamera();acc+=dt;for(let i=0;acc>=.05&&i<4;i++){update(.05);acc-=.05}}uiTick+=dt;saveTick+=dt;if(uiTick>.35){uiTick=0;renderUI()}if(saveTick>8){saveTick=0;save()}draw();requestAnimationFrame(frame)}
